-- =============================================================================
-- Agorbis · 0078 · Comunas de Chile como nivel 4 (D130)
-- -----------------------------------------------------------------------------
-- BORRADOR, NO APLICAR. Vive en supabase/sql-drafts/ hasta que el responsable
-- lo promueva; el número es provisional.
--
-- Generado por scripts/build-chile-level4-draft.mjs; no se edita a mano.
--
-- Va después de 0076 y del borrador de Uruguay.
--
-- Fuente: capa COMUNAS de la DPA 2023 (División Político Administrativa) de
-- SUBDERE, IGM, DIFROL e INE, descargada del geoportal de la IDE Chile el
-- 2026-11-20. 345 comunas bajo sus 16 regiones; la capa no incluye la
-- comuna Antártica, que no tiene municipalidad propia.
--
-- Sólo se usan nombres y códigos: nada derivado de los polígonos, porque la
-- documentación pide validar con la DIFROL los productos derivados de la
-- cartografía. Sin coordenadas, el GPS del onboarding sugiere la región.
-- =============================================================================

begin;

set local search_path = '';

create temporary table level4_rows (
  slug text primary key,
  name text not null,
  parent_slug text not null,
  description text not null,
  lat double precision,
  lng double precision
) on commit drop;


-- Falla cerrado: si el esquema o los datos no son los que se revisaron, no
-- inserta nada en vez de dejar una carga a medias.
do $guard$
declare
  v_missing text;
begin
  select string_agg(distinct i.parent_slug, ', ') into v_missing
  from pg_temp.level4_rows i
  where not exists (
    select 1 from public.communities p
    where p.slug = i.parent_slug and p.level = 3
      and p.path = 'earth.south-america.chile.' || p.slug
  );
  if v_missing is not null then
    raise exception 'AGORBIS_0078_MISSING_REGION: %', v_missing;
  end if;

  select string_agg(i.slug, ', ') into v_missing
  from pg_temp.level4_rows i
  join public.communities c on c.slug = i.slug;
  if v_missing is not null then
    raise exception 'AGORBIS_0078_SLUG_TAKEN: %', v_missing;
  end if;
end;
$guard$;

select i.slug, i.name, 4::smallint, p.id, p.path || '.' || i.slug, '🗺️', i.description, i.lat, i.lng
from pg_temp.level4_rows i
join public.communities p on p.slug = i.parent_slug;

do $check$
declare
  v_expected_level4 constant int := 345;
  v_level4 int;
begin
  select count(*) into v_level4 from public.communities
  where level = 4 and path like 'earth.south-america.chile.%';
  if v_level4 <> v_expected_level4 then
    raise exception 'AGORBIS_0078_UNEXPECTED_TOTALS: nivel 4 %', v_level4;
  end if;
end;
$check$;

-- "on commit drop" no alcanza si otro borrador va en la misma transacción.
drop table pg_temp.level4_rows;

commit;
